"""
Ch01 作业测试。
运行: pytest 01_python_core/ch01/test_ch01_assignment.py -v

测试用例按函数分组(class)。你写完 ch01_assignment.py 后,这里应该全绿。
"""
from ch01_assignment import (
    add,
    swap,
    greet,
    first_or_default,
    describe,
    load_product_names,
)


# ---------- add:动态类型 + 类型注解 ----------
class TestAdd:
    def test_basic(self):
        assert add(1, 2) == 3

    def test_negative(self):
        assert add(-5, 3) == -2

    def test_zero(self):
        assert add(0, 0) == 0

    def test_large_number(self):
        # Python 整数无溢出(对比 Java int 会溢出)
        assert add(10**18, 10**18) == 2 * 10**18


# ---------- swap:元组解包 ----------
class TestSwap:
    def test_ints(self):
        assert swap(1, 2) == (2, 1)

    def test_strings(self):
        assert swap("a", "b") == ("b", "a")

    def test_returns_tuple(self):
        assert isinstance(swap(1, 2), tuple)


# ---------- greet:默认参数 + f-string ----------
class TestGreet:
    def test_default_greeting(self):
        assert greet("Alice") == "Hello, Alice!"

    def test_custom_greeting_positional(self):
        assert greet("Bob", "Hi") == "Hi, Bob!"

    def test_times_repeat_newline_separated(self):
        assert greet("Carl", times=3) == "Hello, Carl!\nHello, Carl!\nHello, Carl!"

    def test_times_one(self):
        assert greet("Dan", times=1) == "Hello, Dan!"


# ---------- first_or_default:truthiness 判空 ----------
class TestFirstOrDefault:
    def test_normal(self):
        assert first_or_default([1, 2, 3]) == 1

    def test_empty_with_default(self):
        assert first_or_default([], "empty") == "empty"

    def test_empty_no_default_returns_none(self):
        # 注意 None 要用 is 判断
        assert first_or_default([]) is None

    def test_empty_keyword_default(self):
        assert first_or_default([], default=99) == 99


# ---------- describe:一切皆对象 ----------
class TestDescribe:
    def test_int(self):
        assert describe(42) == "42 is a int"

    def test_str(self):
        # repr("hi") 带引号
        assert describe("hi") == "'hi' is a str"

    def test_list(self):
        assert describe([1, 2]) == "[1, 2] is a list"

    def test_float(self):
        assert describe(3.14) == "3.14 is a float"


# ---------- load_product_names:工作流验证 ----------
class TestLoadProductNames:
    def test_returns_list_of_10(self):
        names = load_product_names()
        assert isinstance(names, list)
        assert len(names) == 10

    def test_first_name(self):
        assert load_product_names()[0] == "机械键盘"

    def test_all_are_strings(self):
        names = load_product_names()
        assert all(isinstance(n, str) for n in names)

    def test_contains_expected_product(self):
        assert "人体工学椅" in load_product_names()

"""
Ch02 作业测试。运行: pytest 01_python_core/ch02/test_ch02_assignment.py -v

products fixture 来自项目根 conftest.py,加载 assets/mock_data/products.json(10 个商品)。
"""
import pytest

from ch02_assignment import (
    get_top_products_by_price,
    price_range,
    build_price_map,
    group_by_category,
    category_inventory_value,
    all_categories,
    find_cheapest_per_category,
    filter_products,
)


# ---------- get_top_products_by_price:list + 切片 + 排序 ----------
class TestGetTopProductsByPrice:
    def test_top3(self, products):
        assert get_top_products_by_price(products, n=3) == [
            "27寸4K显示器",
            "人体工学椅",
            "降噪耳机",
        ]

    def test_default_n_is_3(self, products):
        assert len(get_top_products_by_price(products)) == 3

    def test_n_more_than_total_returns_all(self, products):
        # n 超过总数应安全返回全部 10 个
        assert len(get_top_products_by_price(products, n=100)) == 10

    def test_descending_order(self, products):
        result = get_top_products_by_price(products, n=5)
        # 第一个必须是最贵的
        assert result[0] == "27寸4K显示器"


# ---------- price_range:tuple 多返回值 ----------
class TestPriceRange:
    def test_min_max(self, products):
        assert price_range(products) == (75.5, 2199.0)

    def test_returns_tuple(self, products):
        assert isinstance(price_range(products), tuple)

    def test_low_less_than_high(self, products):
        low, high = price_range(products)
        assert low < high


# ---------- build_price_map:dict 推导 ----------
class TestBuildPriceMap:
    def test_contains_all(self, products):
        m = build_price_map(products)
        assert len(m) == 10

    def test_lookup(self, products):
        m = build_price_map(products)
        assert m["机械键盘"] == 599.0
        assert m["设计模式"] == 75.5

    def test_is_dict(self, products):
        assert isinstance(build_price_map(products), dict)


# ---------- group_by_category:setdefault 分组 ----------
class TestGroupByCategory:
    def test_category_keys(self, products):
        g = group_by_category(products)
        assert set(g.keys()) == {"电脑外设", "图书", "影音设备", "生活用品"}

    def test_group_counts(self, products):
        g = group_by_category(products)
        assert len(g["电脑外设"]) == 4
        assert len(g["图书"]) == 2
        assert len(g["影音设备"]) == 2
        assert len(g["生活用品"]) == 2

    def test_no_products_lost(self, products):
        g = group_by_category(products)
        assert sum(len(v) for v in g.values()) == 10


# ---------- category_inventory_value:defaultdict 聚合 ----------
class TestCategoryInventoryValue:
    def test_values(self, products):
        v = category_inventory_value(products)
        # 电脑外设: 599*120 + 159*300 + 2199*45 + 269*220 = 277715
        assert v["电脑外设"] == pytest.approx(277715)
        # 生活用品: 199*0(水杯缺货) + 1599*30 = 47970
        assert v["生活用品"] == pytest.approx(47970)

    def test_all_categories_present(self, products):
        assert len(category_inventory_value(products)) == 4

    def test_zero_stock_contributes_zero(self, products):
        # 智能水杯 stock=0,不影响生活用品总值
        v = category_inventory_value(products)
        assert v["生活用品"] == pytest.approx(1599 * 30)


# ---------- all_categories:set 去重 ----------
class TestAllCategories:
    def test_returns_set(self, products):
        assert isinstance(all_categories(products), set)

    def test_contents(self, products):
        assert all_categories(products) == {
            "电脑外设",
            "图书",
            "影音设备",
            "生活用品",
        }

    def test_deduped_to_4(self, products):
        # 10 个商品,但只有 4 个类目
        assert len(all_categories(products)) == 4


# ---------- find_cheapest_per_category:综合 ----------
class TestFindCheapestPerCategory:
    def test_cheapest_names(self, products):
        c = find_cheapest_per_category(products)
        assert c["电脑外设"] == "无线鼠标"      # 159
        assert c["图书"] == "设计模式"          # 75.5
        assert c["影音设备"] == "蓝牙音箱"      # 399
        assert c["生活用品"] == "智能水杯"      # 199(stock=0 但价格最低)


# ---------- filter_products:综合 + 可变默认参数 ----------
class TestFilterProducts:
    def test_no_filter_returns_all_ascending(self, products):
        result = filter_products(products)
        assert len(result) == 10
        assert result[0]["name"] == "设计模式"        # 最便宜 75.5
        assert result[-1]["name"] == "27寸4K显示器"   # 最贵 2199

    def test_min_price(self, products):
        names = [p["name"] for p in filter_products(products, min_price=1000)]
        # >=1000: 耳机1299 / 工学椅1599 / 显示器2199,升序
        assert names == ["降噪耳机", "人体工学椅", "27寸4K显示器"]

    def test_category(self, products):
        names = [p["name"] for p in filter_products(products, category="图书")]
        assert names == ["设计模式", "Python编程:从入门到实践"]

    def test_in_stock_only_excludes_zero_stock(self, products):
        result = filter_products(products, in_stock_only=True)
        assert len(result) == 9  # 排除智能水杯(stock=0)
        assert all(p["stock"] > 0 for p in result)

    def test_combined_filters(self, products):
        names = [p["name"] for p in filter_products(products, min_price=500, category="电脑外设")]
        # 电脑外设 >=500: 键盘599 / 显示器2199,升序
        assert names == ["机械键盘", "27寸4K显示器"]

    def test_min_price_boundary_inclusive(self, products):
        # 边界:>=89 应包含 89,不包含 75.5
        result = filter_products(products, min_price=89, category="图书")
        names = [p["name"] for p in result]
        assert "Python编程:从入门到实践" in names  # 89
        assert "设计模式" not in names              # 75.5 < 89

    def test_sorted_ascending(self, products):
        result = filter_products(products, min_price=200)
        prices = [p["price"] for p in result]
        assert prices == sorted(prices)

"""
Ch03 作业测试。运行: uv run pytest 01_python_core/ch03/test_ch03_assignment.py -v

products fixture 来自项目根 conftest.py(10 个商品)。
error_lines fixture 加载 assets/mock_data/logs.json(20 行日志,含 5 条 ERROR)。
"""
import pytest

from ch03_assignment import (
    cheap_product_names,
    indexed_summary,
    names_and_prices_zipped,
    is_prime,
    iter_error_lines,
    top_n_by_price,
)
from conftest import load_mock_json


@pytest.fixture
def error_lines():
    return load_mock_json("logs.json")


# ---------- cheap_product_names:列表推导(带条件)----------
class TestCheapProductNames:
    def test_under_200(self, products):
        # <200: 无线鼠标159 / Python编程89 / 设计模式75.5 / 智能水杯199
        result = cheap_product_names(products, max_price=200)
        assert set(result) == {
            "无线鼠标",
            "Python编程:从入门到实践",
            "设计模式",
            "智能水杯",
        }
        assert len(result) == 4

    def test_default_max_price_is_200(self, products):
        assert len(cheap_product_names(products)) == 4

    def test_strict_under_100(self, products):
        result = cheap_product_names(products, max_price=100)
        assert set(result) == {"Python编程:从入门到实践", "设计模式"}

    def test_preserves_original_order(self, products):
        # 原顺序里 无线鼠标(id=2) 在 Python编程(id=4) 之前
        result = cheap_product_names(products, max_price=200)
        assert result[0] == "无线鼠标"

    def test_empty_when_none_qualify(self, products):
        assert cheap_product_names(products, max_price=10) == []


# ---------- indexed_summary:enumerate ----------
class TestIndexedSummary:
    def test_format_first(self, products):
        assert indexed_summary(products)[0] == "1. 机械键盘 (¥599.0)"

    def test_format_third(self, products):
        assert indexed_summary(products)[2] == "3. 27寸4K显示器 (¥2199.0)"

    def test_numbering_starts_at_1(self, products):
        assert indexed_summary(products)[0].startswith("1. ")

    def test_count(self, products):
        assert len(indexed_summary(products)) == 10


# ---------- names_and_prices_zipped:zip ----------
class TestNamesAndPricesZipped:
    def test_first_pair(self, products):
        assert names_and_prices_zipped(products)[0] == ("机械键盘", 599.0)

    def test_fifth_pair(self, products):
        assert names_and_prices_zipped(products)[4] == ("设计模式", 75.5)

    def test_all_ten_pairs(self, products):
        result = names_and_prices_zipped(products)
        assert len(result) == 10

    def test_each_is_2tuple(self, products):
        result = names_and_prices_zipped(products)
        assert all(isinstance(t, tuple) and len(t) == 2 for t in result)


# ---------- is_prime:for-else ----------
class TestIsPrime:
    @pytest.mark.parametrize("n", [2, 3, 5, 7, 11, 13, 97])
    def test_primes(self, n):
        assert is_prime(n) is True

    @pytest.mark.parametrize("n", [0, 1, 4, 6, 8, 9, 15, 100])
    def test_not_primes(self, n):
        assert is_prime(n) is False

    def test_two_is_prime_edge(self):
        # 2 是最小素数:range(2,2) 为空,循环不执行 → else 执行
        assert is_prime(2) is True


# ---------- iter_error_lines:生成器 yield ----------
class TestIterErrorLines:
    def test_filters_only_error(self, error_lines):
        result = list(iter_error_lines(error_lines))
        assert len(result) == 5
        assert all("ERROR" in line for line in result)

    def test_is_a_generator(self, error_lines):
        gen = iter_error_lines(error_lines)
        assert hasattr(gen, "__next__")  # 生成器对象有 __next__

    def test_empty_when_no_error(self):
        assert list(iter_error_lines(["INFO a", "WARN b", "DEBUG c"])) == []

    def test_lazy_one_at_a_time(self):
        # 生成器惰性:每次 next 只产出一个
        gen = iter_error_lines(["INFO a", "ERROR boom", "ERROR crash"])
        first = next(gen)
        assert first == "ERROR boom"
        second = next(gen)
        assert second == "ERROR crash"


# ---------- top_n_by_price:迭代器消费 ----------
class TestTopNByPrice:
    def test_top3_descending(self, products):
        result = top_n_by_price(iter(products), n=3)
        assert result == ["27寸4K显示器", "人体工学椅", "降噪耳机"]

    def test_exhausts_the_iterator(self, products):
        it = iter(products)
        top_n_by_price(it, n=2)
        # 迭代器已被消费殆尽
        assert list(it) == []

    def test_n_more_than_total_returns_all(self, products):
        assert len(top_n_by_price(iter(products), n=100)) == 10

    def test_default_n_is_3(self, products):
        assert len(top_n_by_price(iter(products))) == 3

    def test_accepts_generator_expression(self, products):
        gen = (p for p in products)
        assert top_n_by_price(gen, n=1) == ["27寸4K显示器"]

sections.body:
这是 **Java 完全没有**的语法,面试常考,但实际项目用得不多——理解语义即可。

### 语义(一句话)

> `for ... else:` 的 **else 在循环【没有被 `break` 提前终止】时执行**。循环正常跑完(或一次都没进),才走 else。

```python
for i in range(5):
    if i == 3:
        break          # 提前跳出 → else 【不执行】
else:
    print("正常结束")  # 不会打印

for i in range(5):
    if i == 99:
        break          # 永远不会 break → 循环正常跑完
else:
    print("正常结束")  # ✅ 会打印
```

> 🤯 **Java 老手震惊点**:`else` 在这里和 `if` 毫无关系!它更像「`nobreak`」「`completed`」。名字起得差是 Python 公认的历史包袱,但既来之则安之。

### 经典应用:素数判断(本节作业)

不用 for-else,Java 思路要一个标志变量:
```python
# ❌ Java 风格:用 flag
def is_prime(n):
    if n < 2:
        return False
    has_factor = False
    for i in range(2, n):
        if n % i == 0:
            has_factor = True
            break
    return not has_factor
```

用 for-else,**省掉 flag**:
```python
# ✅ Pythonic:for-else
def is_prime(n):
    if n < 2:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False   # 找到因子 → 立即返回(相当于 break 出循环)
    else:
        return True        # 循环一个因子都没找到 → 正常结束 → 走 else → 是素数
```

**关键理解**:`return False` 会让函数直接结束(循环也终止了),所以不会进 else;只有循环**完整跑完没提前退出**,才进 else 返回 True。

> 边界 `is_prime(2)`:`range(2, 2)` 是**空的**,循环一次都不执行,视为「正常结束」→ 走 else → 返回 True。✓(2 是最小素数)

### 什么时候 else 真的「非用不可」

for-else 的价值在:循环外需要知道「中途有没有 break」,而**不想引入 flag 变量**。搜索类场景最典型。但说实话,大多数情况 `return` 或 `any()/all()` 更清晰。记住语义即可,不必强行用。

> ✅ 做 `is_prime` 题:见上面的 Pythonic 版本。

---

